CLAIMS=[
 c(1,[LI,RU],['bookI/propI43.html','bookII/defII.html'],'I.43의 두 보완 평행사변형은 넓이가 같다는 뜻이며 일반적으로 합동을 뜻하지 않는다. II정의의 gnomon은 대각선 주위의 한 평행사변형과 두 보완 부분의 합이다. II.5의 도형 분해에서 어느 넓이를 더하고 빼는지 확인한다.','두 보완 부분만을 gnomon 전체로 세지 않는다. 정의의 일반 평행사변형은 직각으로 한정되지 않으며, II.5의 정사각형은 그 특수한 상황이다. 도형의 표시 크기나 같은 색을 논증으로 대신하지 않는다.'),
 c(2,[LI],['bookI/propI36.html'],'I.36은 같은 길이의 밑변과 같은 두 평행선 사이에 놓인 평행사변형의 넓이를 비교한다. 밑변 길이와 수직 높이 조건을 함께 확인한다.','각 도형 안의 마주 보는 두 변이 평행하다는 사실만으로 두 도형이 같은 두 평행선 사이에 놓인 것은 아니다. 밑변만 같고 높이가 다른 도형까지 등넓이라고 확대하지 않는다.'),
 c(3,[LI],['bookI/propI46.html'],'I.46의 정사각형 작도는 AB와 같은 길이의 AD를 AB에 수직인 방향에서 잡고 평행선을 그은 뒤, 같은 변과 직각을 모두 확인한다. Guide의 불명확한 length C 표현은 본문의 AD=AB와 그림의 D 위치로 구체화해 읽는다.','네 변의 길이가 같다는 조건만으로 정사각형이 되지는 않는다. 실제 컴퍼스 작도나 Guide의 원 개수까지 독립 검증한 것은 아니며, 여기의 좌표 예는 자체 모형이다.'),
 c(4,[LI],['bookI/propI31.html'],'I.31 본문의 각 복사·엇각에 의한 평행선 구성과 Guide의 평행 공준을 이용한 유일성 설명을 구별한다. 자체 과제는 유클리드 평면에서 직선 밖의 점을 조건으로 정한다.','그림이 평행해 보인다는 이유나 존재하는 선 하나를 그린 것만으로 유일성을 입증하지 않는다.2차 연결 원문·비유클리드 모형·실제 작도 전체를 확인한 것은 아니다.'),
 c(5,[LI,RU],['bookI/propI47.html'],'I.47의 대안 증명은 ∠BAC가 직각일 때 빗변 BC 위 수선의 발을 M으로 표시한다. Guide의 작은 삼각형 ABD 표기는 이 대안 그림과 맞지 않는다. 대응을 확인하면 BC/AB=AB/BM, BC·BM=AB²와 BC·CM=AC²로 이어진다.','주증명 그림에 존재하는 D를 대안 증명의 M과 혼합하지 않는다. 삼각형 이름의 순서까지 임의로 같게 쓰지 않으며, 닮음 이론의2차 연결이나 실제 학생 추론을 검증한 것은 아니다.'),
 c(6,[LI],['bookI/propI47.html'],'I.47 주명제는 직각을 낀 두 변 AB,AC의 제곱합이 빗변 BC의 제곱임을 밝힌다. Guide의 대안 증명 마지막에 적힌 AC와 BC의 제곱합은 앞의 두 직사각형 식·주명제와 불일치하므로 AB와 AC로 대조해 정정 설명한다.','온라인 해설의 불일치와 주명제의 옳고 그름을 분리한다.3–4–5 자체 검산은 불일치의 반례이며 모든 직각삼각형의 증명이나 역사 문단·원어 판본 검증을 대신하지 않는다.')]
def p(n,code,q,e,i):return dict(id=f'JEF-P{n:02d}',standard_codes=[code],question=q,expected=e,interpretation=i,student_validated=False)
OBSERVATIONS=[
 p(1,LI,'8×4 직사각형을 대각선 위의 점에서 두 변에 평행하게 나눴을 때 보완 부분이6×1과2×3이다. 두 부분은 어떤 의미로 같은가?','넓이는 각각6으로 같다. 변의 길이쌍은{6,1}과{2,3}으로 달라 합동은 아니다. 같은 넓이와 같은 모양·합동을 구별한다.','이는 I.43의 뜻을 확인하는 자체 수치 모형이다. 원문의 그림을 자로 측정한 자료나 실제 학생의 이해를 관찰한 것이 아니다.'),
 p(2,RU,'II.5의 자체 모형에서5×5 정사각형에서3×3 정사각형을 뺀 gnomon을 세 부분으로 설명하라.','25−9=16이다. 대각선 주위의2×2 부분4와 두 보완 부분3×2,2×3의6+6을 합하면16이다. 보완 부분 둘만 더한12와 구별한다.','gnomon의 일반 정의를 직각 도형으로만 제한하지 않는다. 이 수치는 자체 예이며 원문의 정확한 길이나 원어 판본을 측정·확인한 것이 아니다.'),
 p(3,LI,'밑변3·높이4인 직사각형과 같은 두 수평선 사이의 밑변3 평행사변형을 비교하고, 높이를6으로 바꾸면 어떤가?','앞의 두 넓이는12cm²이고 기울기만으로 달라지지 않는다. 높이가6이면18cm²로 달라 같은 두 평행선 조건을 빠뜨린 비교가 된다.','각 도형에 평행한 변이 있다는 사실과 두 도형의 공통 평행선 조건을 혼동하지 않는다. 수치는 자체 모형이다.'),
 p(4,LI,'한 변5인 정사각형을 만들 때 같은 길이의 네 변만 확인하면 충분한가?','아니다. 변 벡터(5,0),(3,4)로 만든 마름모도 네 변5지만 직각이 아니고 넓이는20이다. 정사각형은 수직 방향과 길이5를 함께 잡아 넓이25를 얻는다.','I.46 본문은 AD=AB와 직각을 함께 확인한다. Guide의 C라는 모호한 길이 표기를 그대로 구현하지 않으며 실제 컴퍼스 동작 검증과 자체 계산을 나눈다.'),
 p(5,LI,'유클리드 평면에서 직선 y=0 밖의 점(0,2)을 지나는 평행선 하나를 그리고, 존재와 유일성의 설명을 나누라.','y=2가 한 평행선이다. I.31 본문은 각 복사와 엇각을 이용한 구성이고 Guide는 평행 공준에 따른 유일성을 별도로 설명한다. 스스로 사용한 조건을 적는다.','이 좌표 예 하나를 모든 기하 체계의 유일성 증명으로 쓰지 않는다.2차 연결 원문·작도 원의 개수·실제 학생의 작도 수행은 미확인이다.'),
 p(6,RU,'AB=3,AC=4인 직각삼각형에서 M을 빗변 BC에 내린 수선의 발로 잡고 Guide의 대응식을 계산하라.','BC=5, BM=9/5, CM=16/5, AM=12/5다. BC·BM=9=AB², BC·CM=16=AC²이며 두 직사각형의 합은25다. 대안 그림의 M과 주증명 그림의 D를 구별한다.','길이와 넓이의 단위를 구별한다. 자체 검산은 소단원 전체 증명·닮음의2차 근거·실제 학생 수행을 확인한 것이 아니다.'),
 p(7,RU,'같은3–4–5 예에서 Guide 마지막 문장의 AC²+BC²와 주명제의 AB²+AC²를 비교하라.','AC²+BC²=16+25=41로 BC²=25와 다르다. 올바른 두 직각변의 합은 AB²+AC²=9+16=25다. 앞의 직사각형 식·주명제·그림을 함께 확인해 정정 근거를 적는다.','주명제가 틀린 것으로 쓰거나 원사이트가 정정됐다고 하지 않는다. 원문 위치·자기 정정·남은 확인 범위를 나누어 기록한다.'),
 p(8,RU,'I.47 Guide의7×7 바깥 정사각형과 네 개의3–4 직각삼각형 넓이로 기울어진 안쪽 정사각형을 점검하라.','바깥49에서 각 삼각형 넓이6을 네 번 빼면25이고 안쪽 변은5다. 그림의 격자·부분 넓이와 계산을 대조하되 표시 면적을 실측값으로 취급하지 않는다.','이 기하 계산은 자체 확인이다. 중국 고문헌·귀속·연대·번역 참고문헌의 역사적 주장을 독립 검증한 것은 아니다.'),
 p(9,LI,'최초II.5 한 페이지 읽기와 이번에 직접 인용6페이지를 더 읽은 범위를 어떻게 구분해 기록할 것인가?','이전 날짜·파일/해시·읽은 범위를 보존하고, 추가 날짜·I.31/36/43/46/47·II정의·본문/Guide·새 그림9개를 따로 적는다. 누적7페이지·그림13개와 새 책의 수를 구별한다.','단순히 링크가 있다는 이유로 원문을 읽었다고 하지 않는다. 출판 연도·다른 번역·원론 전권·2차 링크·동적 애플릿을 확인했다고 확대하지 않는다.'),
 p(10,LI,'직접 인용6페이지를 읽었으므로 II.5의 모든 전제를 독립적으로 증명했고 교수 효과도 확인했다고 해도 되는가?','아니다. 선정 명제의2차 연결·정의·공준·역사 원전·다른 판본은 별도 범위다. 실제 읽은 명제/해설/그림과 자기 검산, 남은 기반 검토와 실제 학생 자료를 구별한다.','직접 연결의 읽기 완료를 전체 원전의 증명 검증·엄격한 학습 선수성·실제 교육 효과로 바꾸지 않는다.')]
UPDATED_CLAIM_LIMITS={'INQ16-15':'이 주장의 최초 대조는 II.5 한 페이지·그림4개다. 후속으로 직접 인용6페이지를 더 읽은 범위는 별도 읽기 이력에 남겼다. 원어 원전·다른 번역·원론 전권·선정 명제들의2차 연결까지 검토했다고 하지 않는다.'}
UPDATED_OBSERVATIONS={
 'INQ-P27':dict(expected='최초II.5의 기하 명제/증명·현대 대수 해설·작도와 식 그림4개를 구별하고, 후속 선정6페이지의 읽기·그림9개 대조를 따로 남긴다. footer1996,2002와 현재 페이지 발행일을 같게 확정하지 않으며 미선정 직접 링크·2차 연결·다른 판본은 미확인으로 둔다.',interpretation='누적7페이지·그림13개의 확인은 원론 전권·원어·다른 번역·애플릿 작동·체계적 문헌 검토 전체의 완료가 아니다.'),
 'INQ-P34':dict(expected='최초에는 II.5의 연결 목록을 읽은 범위로 기록했고, 후속으로 선정6페이지를 실제 대조했다. 활용/일반화의 미선정 직접 링크와 선정 명제가 다시 인용하는 정의/명제·공준의2차 연결은 추가 검토할 범위로 남긴다.',interpretation='링크 존재와 원문 정독을 구별한다. 선정 직접 연결의 확인을 원론 전체의 기반 증명·여러 번역의 체계적 비교·실제 학습 효과로 확대하지 않는다.')}
INTERPRETATIONS={}
for rid in ['SEC_12수과02-01_C04','REV-12수과02-01-1']:
 INTERPRETATIONS[rid,'JEF17-01']=('activity_context','문헌의 등넓이·도형 분해 조건을 자기 탐구의 계산과 설명에 대조한다. I.43과 gnomon 정의에서 어떤 부분을 더하고 빼는지 확인한다.','등넓이를 합동으로 바꾸거나 직접 인용의 독해를 모든 전제·학생의 학습 선수성 검증으로 확대하지 않는다.')
 INTERPRETATIONS[rid,'JEF17-05']=('inference_limit','명제의 주증명·대안 해설·그림의 다른 점 이름과 대응식을 나누어 실제 탐구의 근거를 점검한다.','M과 D의 혼합·단위/대응 오류를 그대로 인용하지 않는다. 자체 검산·한 판본의 직접 연결 독해는 원전 전권·실제 학생 수행의 확인이 아니다.')

def main():
 registry=load_registry();known={c['id'] for c in registry['claims']};newids={c['id'] for c in CLAIMS}
 if newids<=known:
  assert registry['sources'][SOURCE]['snapshot_file']==NOTES;build_report();return
 assert not newids&known
 s=registry['sources'][SOURCE];assert s['snapshot_file']==PRIOR and s['snapshot_sha256']==PRIOR_SHA and s['bibliography_snapshot']==PRIOR_BIB
 assert sha(ROOT/PRIOR)==PRIOR_SHA
 old_source=copy.deepcopy(s);old_notes=load(ROOT/PRIOR)
 html,images=inspect_html_assets(ASSET_SPEC,CACHE);assert len(html)==7 and len(images)==13
 assert html[:1]==old_notes['html_read_manifest'] and images[:4]==old_notes['image_read_manifest']
 old_claims=[copy.deepcopy(c) for c in registry['claims'] if c['source_id']==SOURCE];assert len(old_claims)==3
 old_obs=copy.deepcopy(s['observations']);assert len(old_obs)==8
 assert not {o['id'] for o in OBSERVATIONS}&{o['id'] for src in registry['sources'].values() for o in src.get('observations',[])}
 relations=load(ROOT/'data/revised_relations.json')['relations']
 pairs={(x['id'],c['id']) for x in relations for c in CLAIMS if all(x[k].startswith('standard:') for k in ['from','to']) and {x[k][9:] for k in ['from','to']}<=set(c['standard_codes'])}
 assert pairs==INTERPRETATIONS.keys() and len(pairs)==4
 reviewed=load(ROOT/FILE);old_relation_rows=[copy.deepcopy(x) for x in reviewed['records'] if x['claim_id'] in {c['id'] for c in old_claims}];assert len(old_relation_rows)==2
 bibliography=load(ROOT/'data/sources.json');entry=next(x for x in bibliography if x['id']==SOURCE);old_entry=copy.deepcopy(entry)
 entry.update(title=TITLE,review_scope=SCOPE,does_not_establish=LIMITS,next_review=LIMITS)
 empirical=copy.deepcopy(s['empirical_scope']);empirical['inference_limit']=LIMITS
 notes=copy.deepcopy(old_notes)
 notes.update(date=DATE,read_scope=SCOPE,asset_base_url=BASE,html_read_manifest=html,image_read_manifest=images,empirical_scope=empirical,previous_review=old_source,previous_bibliography=old_entry,previous_claims=old_claims,previous_observations=old_obs,previous_relation_records=old_relation_rows,previous_notes_file=PRIOR,previous_notes_sha256=PRIOR_SHA,reading_log=old_notes['reading_log']+['2026-11-17: 추가 선정6페이지의 본문/Guide·새 삽입그림9개를 실제 대조하고 기존II.5와4그림의 바이트 동일성을 확인했다.'],source_corrections=old_notes['source_corrections']+[dict(location='I.47 Guide, alternate proof',issue='작은 삼각형 ABD 표기는 같은 대안 그림의 M과 맞지 않는다. 마지막 AC²+BC² 표기는 앞의 두 직사각형·주명제와 다르므로 AB²+AC²로 대조해 정정 설명한다.'),dict(location='I.46 Guide and main construction',issue='length C라는 불명확한 표현 대신 본문의 AD=AB·수직 조건과 그림의 D 위치를 확인한다. 실제 컴퍼스 수행·원 개수의 독립 검증으로 쓰지 않는다.')],prerequisite_followup=dict(new_html_pages=6,new_inline_images=9,cumulative_html_pages=7,cumulative_inline_images=13,selected_six_direct_citations_read=True,all_direct_links_read=False,recursive_prerequisite_closure_proved=False,history_originals_verified=False,page_layout_and_applet_verified=False,own_math_not_student_data=True))
 write(ROOT/NOTES,notes)
 history=s.get('snapshot_history',[])+[dict(snapshot_file=PRIOR,snapshot_sha256=PRIOR_SHA,date=old_source['date'],read_scope=old_source['read_scope'])]
 s.update(date=DATE,snapshot_file=NOTES,snapshot_sha256=sha(ROOT/NOTES),snapshot_history=history,bibliography_snapshot=digest(entry),asset_base_url=BASE,html_read_manifest=html,image_read_manifest=images,read_scope=SCOPE,limits=LIMITS,empirical_scope=empirical,method_note='직접 인용6페이지의 본문·해설·그림과 실제 응답 바이트를 대조했다. 모든 전제의 재귀적 검증·원어/역사 원전·동적 배치/애플릿·실제 학생 수행은 미확인이다.',editorial_action='같은 출처를 확장해 새 주장6건·자체 관찰10개를 더하고 기존 주장3건·관찰8개·관계 해석2개의 이력을 보존했다.',display={**s['display'],'title':TITLE})
 for obs in s['observations']:
  if obs['id'] in UPDATED_OBSERVATIONS:obs.update(UPDATED_OBSERVATIONS[obs['id']])
 s['observations']+=copy.deepcopy(OBSERVATIONS)
 for claim in registry['claims']:
  if claim['source_id']==SOURCE:
   claim['empirical_scope']=copy.deepcopy(empirical)
   if claim['id'] in UPDATED_CLAIM_LIMITS:claim['does_not_establish']=UPDATED_CLAIM_LIMITS[claim['id']]
 for claim in copy.deepcopy(CLAIMS):
  claim.update(empirical_scope=copy.deepcopy(empirical),target_snapshots={f'revision:{code}':digest(target_value(f'revision:{code}')) for code in claim['standard_codes']});registry['claims'].append(claim)
 by_claim={c['id']:c for c in registry['claims']};by_relation={x['id']:x for x in relations}
 for row in reviewed['records']:
  if row['claim_id'] in {c['id'] for c in old_claims}:row['claim_snapshot']=claim_snapshot(by_claim[row['claim_id']],s)
 for (rid,cid),(role,finding,limit) in INTERPRETATIONS.items():
  reviewed['records'].append(dict(relation_id=rid,claim_id=cid,role=role,finding=finding,limit=limit,relation_snapshot=relation_snapshot(by_relation[rid]),claim_snapshot=claim_snapshot(by_claim[cid],s)))
 apply_literature_context(relations,registry,registry=reviewed)
 queue=load(ROOT/'data/content_review_queue.json');row=next(x for x in queue['literature_review'] if x['source']['id']==SOURCE);row.update(source=entry,claim_ids=[c['id'] for c in registry['claims'] if c['source_id']==SOURCE])
 write(ROOT/'data/sources.json',bibliography);write(ROOT/'data/literature_claim_reviews.json',registry);write(ROOT/'data/content_review_queue.json',queue);write(ROOT/FILE,reviewed);build_report()
 print('Extended the same Joyce source:6 new claims,10 own tasks,4 new relation records;3 old claim scopes/2 old task scopes and2 relation snapshots explicitly rereviewed')
if __name__=='__main__':main()
